package com.example.miniapp.services

import android.app.*
import android.content.*
import androidx.core.app.NotificationCompat
import com.example.miniapp.runtime.MiniAppActivity
import org.json.*

/** Per-manifest-id durable notification records. Alarm delivery is best-effort on modern Android. */
class MiniNotificationService(private val context:Context, private val appId:String) {
 private val prefs=context.getSharedPreferences("notifications.$appId",Context.MODE_PRIVATE)
 private val alarms=context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
 private fun read():JSONObject=runCatching{JSONObject(prefs.getString("items","{}")?:"{}")}.getOrElse{JSONObject()}
 private fun write(value:JSONObject){prefs.edit().putString("items",value.toString()).apply()}
 fun schedule(input:JSONObject):JSONObject { val id=input.optString("id");if(!Regex("[A-Za-z0-9._-]{1,100}").matches(id))throw NotificationFailure("invalid_params","Invalid notification id");val title=input.optString("title");val body=input.optString("body");if(title.length>120||body.length>1000)throw NotificationFailure("invalid_params","Notification text is too long");val payload=input.optJSONObject("payload")?:JSONObject();if(payload.toString().toByteArray().size>16*1024)throw NotificationFailure("notification_payload_too_large","Payload is too large");val schedule=input.optJSONObject("schedule");val type=schedule?.optString("type")?:"once";val interval=if(type=="interval")schedule?.optInt("intervalMinutes",0)?:0 else 0;val at=nextAt(type,input,schedule,interval);if(at<=System.currentTimeMillis())throw NotificationFailure("invalid_params","Notification time must be in the future");val item=JSONObject().put("id",id).put("title",title).put("body",body).put("payload",payload).put("type",type).put("intervalMinutes",interval).put("schedule",schedule?:JSONObject()).put("nextAt",at);val data=read();data.put(id,item);write(data);registerApp(context,appId);arm(item);return public(item) }
 fun get(id:String):JSONObject?=read().optJSONObject(id)?.let(::public)
 fun list():JSONArray=JSONArray().also{out->read().keys().forEach{key->read().optJSONObject(key)?.let{out.put(public(it))}}}
 fun cancel(id:String){val data=read();data.remove(id);write(data);alarms.cancel(pending(id))}
 fun cancelAll(){read().keys().forEach{cancel(it)}}
 fun deliver(id:String){val item=read().optJSONObject(id)?:return; val channel="mini-app-notifications";val manager=context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;if(android.os.Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(NotificationChannel(channel,"Mini-app notifications",NotificationManager.IMPORTANCE_DEFAULT));val open=Intent(context,MiniAppActivity::class.java).putExtra("appId",appId).putExtra("launchReason","notification").putExtra("notificationId",id).putExtra("launchPayload",item.optJSONObject("payload")?.toString()).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP);val content=PendingIntent.getActivity(context,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);manager.notify((appId+id).hashCode(),NotificationCompat.Builder(context,channel).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(item.optString("title")).setContentText(item.optString("body")).setAutoCancel(true).setContentIntent(content).build());if(item.optString("type")=="once")cancel(id)else{item.put("nextAt",nextAt(item.optString("type"),JSONObject(),item.optJSONObject("schedule"),item.optInt("intervalMinutes")));val data=read();data.put(id,item);write(data);arm(item)}}
 fun restore(){read().keys().forEach{key->read().optJSONObject(key)?.let{arm(it)}}}
 private fun nextAt(type:String,input:JSONObject,schedule:JSONObject?,interval:Int):Long=when(type){"once"->runCatching{java.time.OffsetDateTime.parse(input.optString("at")).toInstant().toEpochMilli()}.getOrElse{throw NotificationFailure("invalid_params","Invalid notification time")};"interval"->if(interval in 15..(7*24*60))System.currentTimeMillis()+interval*60_000L else throw NotificationFailure("invalid_params","Invalid interval");"daily","weekly"->{val hour=schedule?.optInt("hour",-1)?:-1;val minute=schedule?.optInt("minute",-1)?:-1;if(hour !in 0..23||minute !in 0..59)throw NotificationFailure("invalid_params","Invalid schedule time");var date=java.time.ZonedDateTime.now().withHour(hour).withMinute(minute).withSecond(0).withNano(0);if(type=="daily"){if(!date.isAfter(java.time.ZonedDateTime.now()))date=date.plusDays(1)}else{val days=schedule?.optJSONArray("weekdays")?:throw NotificationFailure("invalid_params","weekdays is required");val allowed=(0 until days.length()).map{days.optInt(it,-1)}.toSet();if(allowed.isEmpty()||allowed.any{it !in 1..7})throw NotificationFailure("invalid_params","Invalid weekdays");while(!date.isAfter(java.time.ZonedDateTime.now())||date.dayOfWeek.value !in allowed)date=date.plusDays(1)};date.toInstant().toEpochMilli()};else->throw NotificationFailure("invalid_params","Invalid schedule type")}
 private fun arm(item:JSONObject){val pi=pending(item.getString("id"));alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,item.getLong("nextAt"),pi)}
 private fun pending(id:String)=PendingIntent.getBroadcast(context,id.hashCode(),Intent(context,MiniNotificationReceiver::class.java).putExtra("appId",appId).putExtra("notificationId",id),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
 private fun public(item:JSONObject)=JSONObject().put("id",item.getString("id")).put("title",item.optString("title")).put("body",item.optString("body")).put("nextAt",item.optLong("nextAt")).put("schedule",JSONObject().put("type",item.optString("type")))
 companion object { private fun registerApp(context:Context,id:String){val prefs=context.getSharedPreferences("notification.apps",Context.MODE_PRIVATE);prefs.edit().putBoolean(id,true).apply()}; fun restoreAll(context:Context){context.getSharedPreferences("notification.apps",Context.MODE_PRIVATE).all.keys.forEach{MiniNotificationService(context,it).restore()}} }
}
class NotificationFailure(val code:String,override val message:String):Exception(message)
class MiniNotificationReceiver:BroadcastReceiver(){override fun onReceive(context:Context,intent:Intent){val appId=intent.getStringExtra("appId")?:return;val id=intent.getStringExtra("notificationId")?:return;MiniNotificationService(context,appId).deliver(id)}}
class MiniNotificationBootReceiver:BroadcastReceiver(){override fun onReceive(context:Context,intent:Intent){MiniNotificationService.restoreAll(context)}}
